python3 -c "
import json
with open('/app/resources/treasury_bulletin_2011_03.json') as f:
    data = json.load(f)
# Print keys at top level
print('Top-level keys:', list(data.keys())[:10])
# Look for ESF related data
def find_esf(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'ESF' in k.upper():
                print(f'Found: {path}.{k}')
            if isinstance(v, (dict, list)):
                find_esf(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj[:10]):
            find_esf(item, f'{path}[{i}]')
find_esf(data)
"
